// ═══════════════════════════════════════════════════════════════════════════
// PARSING DES AVIS GOOGLE + GÉNÉRATION DU SLUG
// ═══════════════════════════════════════════════════════════════════════════

const items = $input.all();

return items.map(item => {
  const data = item.json;

  // Récupérer les données du formulaire
  const nomEtablissement = data['Nom de l\'établissement'] || '';
  const siteUrl = data['URL du site existant'] || '';
  const avisGoogle = data['Avis Google'] || '';
  const githubRepo = data['Repository GitHub'] || '';

  // Générer le slug
  const slug = slugify(nomEtablissement);

  // Parser les avis Google
  const avisListe = parseAvisGoogle(avisGoogle);
  const avisClients = avisListe.filter(a => a.type === 'client');

  // URL du callback (à configurer selon ton domaine n8n)
  const callbackUrl = 'https://TON-N8N-DOMAIN/webhook/site-ready';

  return {
    json: {
      nom_etablissement: nomEtablissement,
      site_url: siteUrl,
      github_repo: githubRepo,
      slug: slug,
      avis_json: JSON.stringify(avisClients.slice(0, 10)), // Max 10 avis
      callback_url: callbackUrl,
      stats: {
        nombre_avis: avisClients.length
      }
    }
  };
});

// ═══════════════════════════════════════════════════════════════════════════
// FONCTION SLUGIFY
// ═══════════════════════════════════════════════════════════════════════════

function slugify(text) {
  if (!text) return 'site';

  return text
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[œ]/g, 'oe')
    .replace(/[æ]/g, 'ae')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-+/g, '-')
    .substring(0, 50);
}

// ═══════════════════════════════════════════════════════════════════════════
// FONCTION DE PARSING DES AVIS GOOGLE
// ═══════════════════════════════════════════════════════════════════════════

function parseAvisGoogle(texte) {
  if (!texte || texte.trim() === '') return [];

  const avis = [];

  // Pattern: "X avis[·Y photos] il y a Z temps"
  const startPattern = /(\d+\s+avis(?:·\d+\s+photos?)?)\s+(il y a\s+\d+\s+(?:mois|ans?|semaines?|jours?))/g;

  let matches = [];
  let match;
  while ((match = startPattern.exec(texte)) !== null) {
    matches.push({
      index: match.index,
      endIndex: match.index + match[0].length,
      fullMatch: match[0],
      avisInfo: match[1],
      dateRelative: match[2]
    });
  }

  for (let i = 0; i < matches.length; i++) {
    const currentMatch = matches[i];
    const nextMatch = matches[i + 1];

    // Extraction du nom (texte avant le pattern)
    const beforeText = texte.substring(0, currentMatch.index);
    const lastVisiteIndex = beforeText.lastIndexOf('Visité en');
    const lastEmojiIndex = Math.max(beforeText.lastIndexOf('❤️'), beforeText.lastIndexOf('🙏'));

    let startSearchFrom = Math.max(lastVisiteIndex, lastEmojiIndex, 0);
    if (lastVisiteIndex === startSearchFrom && lastVisiteIndex > 0) {
      const afterVisite = beforeText.substring(lastVisiteIndex);
      const visiteEndMatch = afterVisite.match(/Visité en [a-zéûàâ]+ \d{4}/i);
      if (visiteEndMatch) {
        startSearchFrom = lastVisiteIndex + visiteEndMatch[0].length;
      }
    }

    const nameSection = beforeText.substring(startSearchFrom).trim();

    let authorName = nameSection
      .split(/\d+\s+avis/)[0]
      .replace(/Local Guide·/g, '')
      .replace(/Visité en [a-zéûàâ]+ \d{4}/gi, '')
      .replace(/il y a \d+ (?:mois|ans?|semaines?|jours?)/gi, '')
      .replace(/[❤️🙏]\d*/g, '')
      .replace(/\s+/g, ' ')
      .trim();

    const nameParts = authorName.split(/\s{2,}/);
    authorName = nameParts[nameParts.length - 1].trim();

    // Extraction du contenu
    const afterCurrentMatch = texte.substring(currentMatch.endIndex);
    const nextAvisIndex = nextMatch ? (nextMatch.index - currentMatch.endIndex - 50) : afterCurrentMatch.length;
    const blockText = afterCurrentMatch.substring(0, Math.max(nextAvisIndex, 0));

    let contenu = '';
    const visiteMatch = blockText.match(/Visité en\s+([a-zéûôàâ]+\s+\d{4})/i);
    if (visiteMatch) {
      contenu = blockText.substring(0, visiteMatch.index).trim();
    } else {
      const endPatterns = /(?:❤️|🙏|[A-Z][a-z]+\s+[A-Z][a-z]+\s+(?:Local Guide·)?\d+\s+avis)/;
      const endMatch = blockText.match(endPatterns);
      contenu = endMatch ? blockText.substring(0, endMatch.index).trim() : blockText.trim();
    }

    contenu = contenu
      .replace(/…Plus/g, '')
      .replace(/\s+/g, ' ')
      .trim();

    // Vérifier si c'est une réponse propriétaire
    const isProprietaire = authorName.includes('(propriétaire)') || 
                          authorName.toLowerCase().includes('réflexologie');

    if (isProprietaire) continue; // Skip les réponses proprio

    // Validation
    if (!authorName || authorName.length < 2) continue;
    if (!contenu || contenu.length < 20) continue;

    avis.push({
      type: 'client',
      auteur: authorName,
      texte: contenu,
      rating: 5,
      date_relative: currentMatch.dateRelative
    });
  }

  // Trier par longueur de texte (les plus longs en premier = plus détaillés)
  avis.sort((a, b) => b.texte.length - a.texte.length);

  return avis;
}
